helper:
function addCards(chapter,entries){
 const cards=load("cards"),knowledge=load("knowledge"),handling=load("handling"),figs=load("figures");
 const chapterNames={11:"细胞信号转导",12:"细胞周期与细胞分裂",13:"细胞增殖调控与癌细胞"};
 const existing=cards.filter(c=>c.chapter===chapter).length;let n=existing,k=knowledge.filter(x=>x.knowledge_id.startsWith("KP-CN"+chapter+"-")).length;
 for(const e of entries){
 const id="RB-CN"+chapter+"-"+String(++n).padStart(4,"0");
 const ans=[],rub=[],ids=[];const su=[...new Set(e.points.flatMap(p=>p.units).concat(e.extra_units||[]))];
 e.points.forEach((p,i)=>{const a="A"+(i+1),r="R"+(i+1),kid="KP-CN"+chapter+"-"+String(++k).padStart(4,"0");ids.push(kid);ans.push({anchor:a,text:p.answer});rub.push({anchor:r,text:p.score});knowledge.push({knowledge_id:kid,knowledge:p.knowledge,source_units:p.units,card_id:id,answer_anchor:a,rubric_anchor:r,explicit_recall:true,status:"covered",verified:p.verified,verification_note:p.verification_note,source_excerpt:p.source_excerpt||'',question_requirement:e.front,rubric_requirement:p.score});});
 const images=(e.images||[]).map(i=>({figure_id:i.figure_id,side:i.side||"back",annotation:i.annotation}));
 cards.push({id,type:"Basic",chapter,front:e.front,answer:ans,rubric:rub,detail:e.detail||"",basis:e.basis||"教材直接支持",source_units:su,knowledge_ids:ids,images,tags:["学科::细胞生物学","章节::第"+chapter+"章_"+chapterNames[chapter],"主题::"+e.theme,"任务::"+(e.task||"解释机制"),"卡片编号::"+id]});
 for(const u of su){const a=handling[u]||{status:"mapped",cards:[],reason:"知识已对应明确题干、完整答案和逐点必答要求。"};if(!a.cards.includes(id))a.cards.push(id);handling[u]=a;}
 }
 store("cards",cards);store("knowledge",knowledge);store("handling",handling);return {cards:cards.length,knowledge:knowledge.length,last_id:cards.at(-1)?.id};
}
